    except Exception: continue
    msg=d.get("message") or {}
    c=msg.get("content")
    if not isinstance(c,list): continue
    for b in c:
        if isinstance(b,dict) and b.get("type")=="tool_use" and b.get("name")=="Bash":
            inp=b.get("input") or {}
            cmd=inp.get("command"); desc=inp.get("description")
            if cmd and desc: pairs.append({"nl":desc,"cmd":cmd})
print(f"Bash calls with a description: {len(pairs)}")
lens=[len(p['cmd']) for p in pairs]
lens.sort()
print(f"command length chars: median {lens[len(lens)//2]}  p90 {lens[int(len(lens)*.9)]}  max {lens[-1]}")
import re
SPLIT=re.compile(r"\|\||&&|\||;")
def util(c):
    m=re.sub(r'"[^"]*"|\'[^\']*\'','""',c); seg=SPLIT.split(m)[0]
    for t in seg.split():
        if t in ("sudo","time","nohup","command","cd"): continue
        if "=" in t and not t.startswith("-"): continue
        return t.strip("()`$")
    return ""
u=collections.Counter(util(p["cmd"]) for p in pairs)
print(f"distinct leading utilities: {len(u)}")
for k,v in u.most_common(12): print(f"   {k:<14} {v:>4}  {v/len(pairs):.3f}")
json.dump(pairs, open("raw_pairs.json","w"), indent=1)
